const int8 = new Int8Array([1, 2, 3])
const uint8 = new Uint8Array([255, 0, 128])
const float32 = new Float32Array([1.5, 2.5])
return {
  int8: Array.from(int8),
  uint8: Array.from(uint8),
  float32: Array.from(float32),
  float32Bytes: float32.BYTES_PER_ELEMENT
}
